            {"id": "AC12", "given": "a pantry row is created with quantity zero", "when": "it is saved", "then": "it is accepted as valid rather than rejected"},
            {"id": "AC13", "given": "an existing pantry row's quantity is decremented to zero as the product runs out", "when": "the update is saved", "then": "the row is retained rather than deleted, preserving the product in the pantry"}
          ]
        },
