      "title": "Browse and inspect the dead-letter queue",
      "stories": [
        {
          "id": "S1",
          "statement": "As an operator, I can browse a subscription's dead-lettered messages with paging so I can see what is stuck without querying the journal directly.",
          "domains": ["backend"],
          "acceptance_criteria": [
            {"id": "AC1", "given": "a subscription with more dead-lettered messages than fit on one page", "when": "the operator requests the DLQ listing with no paging cursor", "then": "the first page of dead-lettered messages is returned along with a cursor for the next page"},
            {"id": "AC2", "given": "a cursor returned from a previous DLQ listing page", "when": "the operator requests the DLQ listing using that cursor", "then": "the next page is returned continuing from where the prior page left off, with no duplicate or skipped messages"},
            {"id": "AC3", "given": "a subscription with no dead-lettered messages", "when": "the operator requests the DLQ listing", "then": "an empty page is returned with no next-page cursor"}
          ]
        },
        {
          "id": "S2",
          "statement": "As an operator, I can inspect a single dead-lettered message's payload and failure reason so I can understand why it failed.",
          "domains": ["backend"],
          "acceptance_criteria": [
            {"id": "AC1", "given": "the id of a currently dead-lettered message", "when": "the operator requests that message's detail", "then": "the response includes the message's full original payload"},
            {"id": "AC2", "given": "the id of a currently dead-lettered message", "when": "the operator requests that message's detail", "then": "the response includes the failure reason recorded at the time the message was dead-lettered"},
            {"id": "AC3", "given": "an id that does not correspond to a currently dead-lettered message", "when": "the operator requests that message's detail", "then": "a not-found result is returned"}
          ]
        }
      ]
    },
    {
      "id": "E2",
